# Code Generated by Sidekick is for learning and experimentation purposes only.
-- database/init.sql

CREATE TABLE urls (
    id BIGSERIAL PRIMARY KEY,
    url TEXT NOT NULL,                          -- Original long URL
    short_url VARCHAR(10) UNIQUE NOT NULL,      -- Shortened code
    created_at TIMESTAMP DEFAULT NOW(),
    expiration_time TIMESTAMP,                  -- NULL = never expires
    created_by VARCHAR(100),                    -- User/API identifier
    status VARCHAR(20) DEFAULT 'active',        -- active, expired, disabled
    clicks BIGINT DEFAULT 0,                    -- Total clicks
    last_accessed TIMESTAMP,                    -- Last redirect time

    -- Indexes for performance
    INDEX idx_short_url (short_url),
    INDEX idx_status (status),
    INDEX idx_created_by (created_by),
    INDEX idx_expiration (expiration_time)
);

-- Analytics table for detailed click tracking
CREATE TABLE click_events (
    id BIGSERIAL PRIMARY KEY,
    short_url VARCHAR(10) NOT NULL,
    clicked_at TIMESTAMP DEFAULT NOW(),
    user_agent TEXT,
    ip_address VARCHAR(45),
    referrer TEXT,
    country VARCHAR(100),

    FOREIGN KEY (short_url) REFERENCES urls(short_url)
);
